.darma-loader-darma-b8-droplet-ripple { --accent: var(--loader-color, #38bdf8); --accent-2: var(--loader-secondary-color, #0284c7); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; }
.darma-loader-darma-b8-droplet-ripple span { position: absolute; left: 50%; top: 0; width: calc(var(--loader-size, 80px) * .16); height: calc(var(--loader-size, 80px) * .16); margin-left: calc(var(--loader-size, 80px) * -.08); border-radius: 50% 50% 50% 0; background: linear-gradient(135deg, var(--accent), var(--accent-2)); animation: darma-loader-darma-b8-droplet-darma-loader-darma-b8-droplet-ripple-ripple-drip calc(var(--loader-speed, 1s) * 1.8) ease-in infinite; }
.darma-loader-darma-b8-droplet-ripple::before, .darma-loader-darma-b8-droplet-ripple::after { content: ''; position: absolute; left: 50%; bottom: 8%; width: calc(var(--loader-size, 80px) * .24); height: calc(var(--loader-size, 80px) * .1); margin-left: calc(var(--loader-size, 80px) * -.12); border: 2px solid var(--accent-2); border-radius: 50%; opacity: 0; animation: darma-loader-darma-b8-droplet-ripple-ripple calc(var(--loader-speed, 1s) * 1.8) ease-out infinite; }
.darma-loader-darma-b8-droplet-ripple::after { animation-delay: calc(var(--loader-speed, 1s) * .28); }
@keyframes darma-loader-darma-b8-droplet-ripple-drip { 0% { transform: translateY(0) rotate(45deg) scale(1); } 55% { transform: translateY(calc(var(--loader-size, 80px) * .72)) rotate(45deg) scale(1); opacity: 1; } 62% { transform: translateY(calc(var(--loader-size, 80px) * .72)) rotate(45deg) scale(.2); opacity: .3; } 63%, 100% { opacity: 0; } }
@keyframes darma-loader-darma-b8-droplet-ripple-ripple { 0%, 55% { transform: scale(.3); opacity: 0; } 62% { opacity: .85; } 100% { transform: scale(1.6); opacity: 0; } }

